import type { ResponsiveImage } from '@/types/media'
import { imageManifest } from './generated/imageManifest'

/**
 * Central registry of real brand and campaign media. Every image used on the site comes from here.
 *
 * - Files: originals in /assets/originals (never edited), optimized variants in /public/assets/<group>/,
 *   generated by `npm run assets` (scripts/optimize-assets.mjs), which also writes ./generated/imageManifest.ts.
 * - This file adds what the pipeline cannot know: alt text, subject, placement and attribution.
 * - Attribution: client relationships for these creatives are UNCONFIRMED — captions use neutral category
 *   labels, never client names or results. Update `attribution` once confirmed.
 * - Inventory and placement rationale: docs/assets/ASSET_INVENTORY.md
 * - Exceptions (own generated manifests, so their metadata ships only with a code-split section): the Scalvo UI
 *   layers in ./scalvoImages.ts and the showcase reels in ./showcaseVideos.ts.
 */

type ManifestEntry = (typeof imageManifest)[keyof typeof imageManifest]

export type AssetMeta = {
  alt: string
  /** What the asset actually shows (from visual inspection, not the filename). */
  subject: string
  /** Where it is used. One placement per asset — no repeats across sections. */
  placement: string
  attribution: 'confirmed-client' | 'unconfirmed' | 'concept'
  objectPosition?: string
}

export type RegisteredImage = ResponsiveImage & Omit<AssetMeta, 'alt' | 'objectPosition'>

function registerImage(entry: ManifestEntry, meta: AssetMeta): RegisteredImage {
  return {
    id: entry.id,
    width: entry.width,
    height: entry.height,
    dominantColor: entry.dominantColor,
    hasAlpha: entry.hasAlpha,
    avif: entry.variants.avif,
    webp: entry.variants.webp,
    ...meta,
  }
}

